"""LRU cache with per-entry TTL expiration."""
import time


class LRUTTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = int(capacity)
        self._clock = clock
        self._data = {}  # key -> [value, expires_at or None]

    def set(self, key, value, ttl=None):
        expires = None if ttl is None else self._clock() + ttl
        self._data[key] = [value, expires]
        if len(self._data) > self.capacity:
            oldest = next(iter(self._data))
            del self._data[oldest]

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default

        # Expiration is checked when the entry is accessed so an expired
        # value can never be returned and does not remain resident.
        expires = entry[1]
        if expires is not None and self._clock() >= expires:
            del self._data[key]
            return default

        # Dictionaries preserve insertion order. Remove and reinsert a
        # successfully accessed entry to move it to the MRU end.
        del self._data[key]
        self._data[key] = entry
        return entry[0]

    def delete(self, key):
        self._data.pop(key, None)

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)

